  'UI_VOL_CDP_MOUNT_VERIFY_DESC' => '挂载验证',
  'UI_VOL_CDP_COMPLETE_MACHINE_VERIFY_DESC' => '整机验证',

  'UI_VOL_CDP_BACKUP_TASK_STANDBY_TYPE_DESC' => '挂载接管:使用代理客户端作为备机，需要事先准备好和主机一样的操作系统，并装好与主机一致的应用软件及备份插件.<br><br>
                                    整机接管:使用容灾演练平台作为备机，需要根据主机资源配置虚拟备机的计算资源及网络资源.',

  'UI_VOL_CDP_STANDBY_TYPE_DESC' => '挂载验证/接管:使用代理客户端作为备机，需要事先准备好和主机一样的操作系统，并装好与主机一致的应用软件及备份插件.<br><br>
                                    整机验证/接管:使用容灾演练平台作为备机，需要根据主机资源配置虚拟备机的计算资源及网络资源.',

  'UI_VOL_CDP_REAL_SYNCS_MODE_DESC' => '该模式只需在生产系统上安装客户端，即可实现将数据实时备份到容灾备份系统，一旦生产系统发生故障，即可执行备份数据任意时间点回退。<br>该模式RPO≈0，可以实现故障场景下的数据最小化丢失。 <br><br>',

  'UI_VOL_CDP_REAL_REPLICATION_MODE_DESC' => '该模式需要用户提前部署备用主机，在生产主机上安装客户端后开始进行实时数据保护，期间会将生产主机的变化数据实时同步至备机，保证备机和主机的数据完全一致。<br><br>',
  'UI_VOL_CDP_REAL_SYNC_AND_REAL_REPLI_MODE_DESC' => '该模式有初始同步和实时同步2个阶段，适用于对数据RPO以及应用高可用有一定要求的备份场景. 用户可根据需要，选择备机或备份集中的任意时间点进行恢复或手动接管.<br><br>',
  'UI_VOL_CDP_REPLICATION_INIT_SYSNC_DESC' => '将选定的数据源主机卷中已存在的原始数据，以及启动任务后产生的变化数据，完全同步到备机中.',
  'UI_VOL_CDP_REPLICATION_REAL_TIME_SYSNC_DESC' => '将选定的数据源主机卷在初始同步完成后产生的变化数据，实时同步到备机中.',


  'UI_VOL_CDP_REAL_SYNC_OR_REAL_REPLI' => '该模式只需在用户生产系统上安装客户端，即可实现将数据实时备份到容灾备份系统。一旦生产系统发生故障，即可执行任意时间点的数据恢复或接管。<br>该模式RPO≈0，可以实现故障场景下的数据最小化丢失，对于接管场景，RTO≈0，可以保障业务连续性。<br><br>',
  'UI_VOL_CDP_REAL_COPY_AND_AUTO_TAKEOVER_DESC' => '该模式需要用户提前部署备用主机，在生产主机上安装客户端后开始进行实时数据保护，期间会将生产主机的变化数据实时同步至备机，保证备机和主机的数据完全一致.当生产主机发生故障时，可以直接由备机进行接管。<br>该模式RPO≈0，RTO≈0，可以保障业务连续性。<br><br>',
  'UI_VOL_CDP_REAL_COPY_AND_BACKUP_AUTO_TAKEOVER_DESC' => '该模式有初始同步、实时同步、接管启动、接管中、回切初始同步、回切实时同步6个阶段.适用于对业务数据RPO以及应用高可用有较高要求的备份场景,用户也可根据需要，选择备机或备份集中的任意时间点进行恢复或手动接管.<br><br>',

  'UI_VOL_CDP_REAL_TIME_TAKEOVER_INIT_SYNC_DESC' => '将选定的数据源主机卷中已存在的原始数据，以及启动任务后产生的变化数据，完全同步到备份系统中.<br>',
  'UI_VOL_CDP_MODE_DESC' => '此模式包含以下任务阶段:',
  'UI_VOL_CDP_REAL_TIME_NO_TAKEOVER_INIT_SYNC_DESC' => '将选定的数据源主机卷在初始同步完成后产生的变化数据，实时同步到备份系统中.<br>',
  'UI_VOL_CDP_BACKUP_REAL_TIME_SYNC' => '将选定的数据源主机卷在初始同步完成后产生的变化数据，实时同步到备份系统中，生成备份集，用于恢复与接管.<br>',
  'UI_PLATFORM_DES_BACK_SYN_DESC' => '回切初始同步完成后，产生的变化数据继续反向同步到数据源主机中，若打开接管回切配置中【备份数据】选项，则变化数据同时同步到备份服务器中.此时，可执行停止接管操作，将业务回切到数据源主机，由数据源主机对外提供服务.<br>',


  'UI_VOL_CDP_INIT_SYNC_DESC' => '初始同步：将选定的数据卷中已存在的原始数据，完全同步到备份服务器.初始同步完成后，进入实时同步阶段.<br>',
  'UI_PLATFORM_DES_TAKEOVER_STARTING_DESC' => '接管启动：当主机应用或网络发生故障后，启动接管业务流程，将主机数据及应用接管到备机<br>',
  'UI_PLATFORM_DES_IN_TAKEOVER_DESC' => ' 接管中：  接管启动成功后，备机将拉起数据和应用，代替主机，对外提供服务.当环境主机故障解除，可以执行回切操作',
  'UI_PLATFORM_DES_BACK_INITIAL_SYN_DESC' => '回切初始同步是将备机在接管过程中生成的数据反向同步到主机和备份服务器，然后任务进行回切实时同步阶段.
                                        在回切实时同步及后续过程中生成的数据反向同步到主机和备份服务器.此时，可执行停止接管操作，将业务回切到主机，由主机对外提供服务.<br>',
  'UI_VOL_CDP_TAKEOVER_TYPE_CHANGE' => '选择接管类型',
  'UI_VOL_CDP_MOUNT_TAKEOVER' => "挂载接管",
  'UI_VOL_CDP_COMPLETE_MACHINE_TAKEOVER' => "整机接管",

  'UI_VOL_CDP_TEMP_USE_SCENE' => '应用场景',
  'UI_VOL_CDP_TEMP_USE_SCENE_DESC' => '在接管场景中，备机会接管主机的应用以及IP，拉起应用后对外提供服务.<br><br>
