  'UI_STRATEGY_FULL_TOOLTIPS' => '<b>完全备份：</b>将会对备份源的全部数据进行备份,备份完成后备份数据成为一个完全备份时间点,备份的是所有数据',
  'UI_STRATEGY_INCR_TOOLTIPS' => '<b>增量备份：</b>在上一次备份的基础上对源数据进行备份,依赖上一个增量时间点或者完备时间点,只备份上一次备份完成到当前时间的变化数据',
  'UI_STRATEGY_DIFF_TOOLTIPS' => '<b>差异备份：</b>在上一次完全备份的基础上对源数据进行备份,依赖上一个完全备份点,只备份上一次完全备份完成到当前时间的变化数据',
  'UI_STRATEGY_PINCR_TOOLTIPS' => '<b>永久增量：</b>在做备份任务时,只需做一次完全备份,以后只做增量备份.减少完全备份次数,节省备份存储空间及带宽资源',
  'UI_STRATEGY_THREE_TOOLTIPS' => '一般情况下,建议每周/每月做一次完全备份,每天做一次增量备份,增量备份和差异备份不能同时设置,如果只设置了增量备份或差异备份,任务首次会自动降级为完全备份',
  'UI_STRATEGY_LOG_TOOLTIPS' => '<b>(归档)日志备份：</b>在上一次备份的基础上,对变化的日志数据进行备份',
  'UI_STRATEGY_LOG_TOOLTIPS_TIDB' => '<b>(归档)日志备份：</b>在上一次备份的基础上,对变化的日志数据进行备份,依赖于上一个日志时间点或完备时间点。日志备份跟随完全备份启动，单独停止日志备份后，需要启动完全备份才能继续进行日志备份',
