  'UI_BACKUP_TRANSPORT_ADAPTIVE' => '自适应传输',
  'UI_BACKUP_TRANSPORT_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>加密传输：针对网络传输模式下的传输通道进行SSL加密<br><br>热添加传输(LAN-Free) : 备份数据通过SAN网络把磁盘附加到备份服务器上,需要先配置LAN-Free存储<br><br>如果SAN传输未生效,会自动使用网络传输',
  'UI_BACKUP_TRANSPORT_VMWARE_SELECT_TIPS' => 'NBD传输:备份数据将通过LAN网络传输到备份存储<br><br>NBD-SSL传输:在NBD传输的基础上对传输通道进行SSL加密<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>热添加传输 : 通过ESXI的SCSI HotAdd特性将目标磁盘挂载到备份服务器/代理上，实现数据的直接访问<br><br>如果SAN传输未生效,会自动使用NBD传输',
  'UI_BACKUP_TRANSPORT_ICS_VVDK_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储',
  'UI_BACKUP_TRANSPORT_SELECT_NBD_TIPS' => '【网络会自动切换，若有专用备份网络则优先使用专用网络传输，否则才会切换至管理网络进行传输】',
  'UI_BACKUP_TRANSPORT_HUAWEI_KVM_SELECT_TIPS' => '根据磁盘所在存储类型，自动选择合适的传输模式',
  'UI_BACKUP_TRANSPORT_RHV_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>ImageIO传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质',
  'UI_BACKUP_TRANSPORT_HUAWEI_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>加密传输：针对网络传输模式下的传输通道进行SSL加密<br><br>如果SAN传输未生效,会自动使用网络传输',
  'UI_BACKUP_TRANSPORT_LEIXEN_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>如果SAN传输未生效,会自动使用网络传输',
  'UI_BACKUP_TRANSPORT_OPENSTACK_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br>如果SAN传输未生效,会导致任务失败<br><br>代理:通过代理资源池或单个传输代理传输到备份存储',
  'UI_BACKUP_TRANSPORT_XENSERVER_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储<br><br>NBD传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质,XenServer7.3及以上支持<br><br>SAN+NBD传输:备份数据通过NBD方式SAN传输到备份存储<br><br>如果SAN传输未生效,会自动使用网络传输',
  'UI_BACKUP_TRANSPORT_XENSERVER_SELECT_TIPS2' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>SAN传输(LAN-Free):备份数据通过SAN传输到备份存储,需要先配置LAN-Free存储',
  'UI_BACKUP_TRANSPORT_SCP_SELECT_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>传输代理是部署在虚拟化平台或者数据中心的物理服务器上的代理,用于提高任务效率,节省网络带宽.',
  'UI_BACKUP_TRANSPORT_HOTADD' => '热添加传输',
  'UI_BACKUP_TRANSPORT_SELECT_NO_LANFREE_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>加密传输：针对网络传输模式下的传输通道进行SSL加密',
  'UI_BACKUP_TRANSPORT_VMWARE_SELECT_NO_LANFREE_TIPS' => 'NBD传输:备份数据将通过LAN网络传输到备份存储<br><br>NBD-SSL传输:在NBD传输的基础上对传输通道进行SSL加密<br><br>热添加传输 : 通过ESXI的SCSI HotAdd特性将目标磁盘挂载到备份服务器/代理上，实现数据的直接访问',
  'UI_BACKUP_TRANSPORT_RHV_SELECT_NO_LANFREE_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>ImageIO传输:通过虚拟化平台提供的接口将备份数据传输到备份存储介质',
  'UI_BACKUP_TRANSPORT_HUAWEI_SELECT_NO_LANFREE_TIPS' => '网络传输:备份数据将通过LAN网络传输到备份存储<br><br>加密传输：针对网络传输模式下的传输通道进行SSL加密',
